page Sim "/" {
  state paused = false
  state frames = 0
  state count = 0
  ref box
  ref balls
  ref raf

  fn makeBall() {
    let r = 10
    return {
      x: r + Math.random() * (400 - 2 * r),
      y: r + Math.random() * (300 - 2 * r),
      vx: (Math.random() * 2 - 1) * 4,
      vy: (Math.random() * 2 - 1) * 4,
      r: r
    }
  }

  fn reset() {
    let list = []
    for (let i = 0; i < 5; i++) {
      list.push(makeBall())
    }
    balls = list
    count = balls.length
    frames = 0
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
  }

  fn clamp(b) {
    if b.x < b.r {
      b.x = b.r
      b.vx = Math.abs(b.vx)
    }
    if b.x > 400 - b.r {
      b.x = 400 - b.r
      b.vx = -Math.abs(b.vx)
    }
    if b.y < b.r {
      b.y = b.r
      b.vy = Math.abs(b.vy)
    }
    if b.y > 300 - b.r {
      b.y = 300 - b.r
      b.vy = -Math.abs(b.vy)
    }
  }

  fn step() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      clamp(b)
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let dist = Math.sqrt(dx * dx + dy * dy)
        let minDist = a.r + c.r
        if dist < minDist {
          if dist == 0 {
            dx = 1
            dy = 0
            dist = 1
          }
          let nx = dx / dist
          let ny = dy / dist
          let approaching = (c.vx - a.vx) * nx + (c.vy - a.vy) * ny
          if approaching < 0 {
            let tvx = a.vx
            let tvy = a.vy
            a.vx = c.vx
            a.vy = c.vy
            c.vx = tvx
            c.vy = tvy
          }
          let overlap = (minDist - dist) / 2
          a.x -= nx * overlap
          a.y -= ny * overlap
          c.x += nx * overlap
          c.y += ny * overlap
          clamp(a)
          clamp(c)
        }
      }
    }
  }

  fn draw() {
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#2563eb"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    if !paused {
      step()
      draw()
      frames++
    }
    raf = requestAnimationFrame(loop)
  }

  mount {
    reset()
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  style {
    .board { border: 1px solid #ccc; }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas" tag=h1
    canvas id="sim" width=400 height=300 ref=box class="board"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> paused = !paused
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

page Sim "/" {
  ref box
  ref ctx
  ref balls
  ref raf
  state count = 0
  state frames = 0
  state paused = false

  fn makeBall() {
    return {
      x: 10 + Math.random() * 380,
      y: 10 + Math.random() * 280,
      vx: (Math.random() * 2 - 1) * 3,
      vy: (Math.random() * 2 - 1) * 3
    }
  }

  fn reset() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(makeBall())
    }
    count = balls.length
    frames = 0
    draw()
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
    if paused {
      draw()
    }
  }

  fn step() {
    let R = 10
    let W = 400
    let H = 300
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let d = Math.hypot(dx, dy)
        if d < 2 * R && d > 0 {
          let nx = dx / d
          let ny = dy / d
          let rel = (c.vx - a.vx) * nx + (c.vy - a.vy) * ny
          if rel < 0 {
            let tvx = a.vx
            let tvy = a.vy
            a.vx = c.vx
            a.vy = c.vy
            c.vx = tvx
            c.vy = tvy
          }
          let overlap = (2 * R - d) / 2
          a.x -= nx * overlap
          a.y -= ny * overlap
          c.x += nx * overlap
          c.y += ny * overlap
        }
      }
    }
    for b in balls {
      if b.x < R {
        b.x = R
        b.vx = Math.abs(b.vx)
      }
      if b.x > W - R {
        b.x = W - R
        b.vx = -Math.abs(b.vx)
      }
      if b.y < R {
        b.y = R
        b.vy = Math.abs(b.vy)
      }
      if b.y > H - R {
        b.y = H - R
        b.vy = -Math.abs(b.vy)
      }
    }
  }

  fn draw() {
    if !ctx {
      ctx = box.getContext("2d")
    }
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#2563eb"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, 10, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    step()
    draw()
    frames++
    raf = requestAnimationFrame(loop)
  }

  fn togglePause() {
    if paused {
      paused = false
      raf = requestAnimationFrame(loop)
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  fn restart() {
    reset()
  }

  mount {
    reset()
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas id="sim" ref=box width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" -> add()
      button (paused ? "Reanudar" : "Pausar") primary -> togglePause()
      button "Reiniciar" -> restart()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}
